/* @lc app=leetcode id=3197 lang=kotlin */ class Solution { fun bb(g: Array<IntArray>, r1: Int, r2: Int, c1: Int, c2: Int): Int = if (r1 > r2 || c1 > c2) 0 else (r1..r2).flatMap { r -> (c1..c2).filter { g[r][it] == 1 }.map { r to it } }.let { o -> if (o.isEmpty()) 0 else (o.maxOf { it.first } - o.minOf { it.first } + 1) * (o.maxOf { it.second } - o.minOf { it.second } + 1) } fun minimumSum(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> listOf((0 until m - 1).flatMap { i -> (i + 1 until m - 1).map { j -> bb(grid, 0, i, 0, n - 1) + bb(grid, i + 1, j, 0, n - 1) + bb(grid, j + 1, m - 1, 0, n - 1) } }, (0 until n - 1).flatMap { i -> (i + 1 until n - 1).map { j -> bb(grid, 0, m - 1, 0, i) + bb(grid, 0, m - 1, i + 1, j) + bb(grid, 0, m - 1, j + 1, n - 1) } }, (0 until m - 1).flatMap { i -> (0 until n - 1).flatMap { c -> listOf(bb(grid, 0, i, 0, n - 1) + bb(grid, i + 1, m - 1, 0, c) + bb(grid, i + 1, m - 1, c + 1, n - 1), bb(grid, i + 1, m - 1, 0, n - 1) + bb(grid, 0, i, 0, c) + bb(grid, 0, i, c + 1, n - 1)) } }, (0 until n - 1).flatMap { c -> (0 until m - 1).flatMap { r -> listOf(bb(grid, 0, m - 1, 0, c) + bb(grid, 0, r, c + 1, n - 1) + bb(grid, r + 1, m - 1, c + 1, n - 1), bb(grid, 0, m - 1, c + 1, n - 1) + bb(grid, 0, r, 0, c) + bb(grid, r + 1, m - 1, 0, c)) } }).flatten().min() } } }